"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[5949],{9229(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/concepts/","label":"Course Overview","docId":"index","unlisted":false},{"type":"category","label":"1. Foundations of Algorithms","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/concepts/foundations-of-algorithms/algorithmic-thinking","label":"Algorithmic Thinking","docId":"foundations-of-algorithms/algorithmic-thinking","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/case-study-pairwise","label":"Case Study - Pairwise Product","docId":"foundations-of-algorithms/case-study-pairwise","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/data-structures","label":"Data Structures","docId":"foundations-of-algorithms/data-structures","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/measuring-efficiency","label":"Measuring Efficiency","docId":"foundations-of-algorithms/measuring-efficiency","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/complexity-analysis","label":"Complexity Analysis","docId":"foundations-of-algorithms/complexity-analysis","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/asymptotic-notation","label":"Asymptotic Notation","docId":"foundations-of-algorithms/asymptotic-notation","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/growth-rates","label":"Growth Rates and Predictions","docId":"foundations-of-algorithms/growth-rates","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/complexity-of-loops","label":"Complexity of Loops","docId":"foundations-of-algorithms/complexity-of-loops","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/searching-case-studies","label":"Searching Case Studies","docId":"foundations-of-algorithms/searching-case-studies","unlisted":false}],"href":"/concepts/category/1-foundations-of-algorithms"},{"type":"category","label":"2. Fundamental Problem Domains","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/concepts/fundamental-problem-domains/the-sorting-problem","label":"The Sorting Problem","docId":"fundamental-problem-domains/the-sorting-problem","unlisted":false},{"type":"link","href":"/concepts/fundamental-problem-domains/bubble-sort","label":"Bubble Sort","docId":"fundamental-problem-domains/bubble-sort","unlisted":false},{"type":"link","href":"/concepts/fundamental-problem-domains/insertion-sort","label":"Insertion Sort","docId":"fundamental-problem-domains/insertion-sort","unlisted":false},{"type":"link","href":"/concepts/fundamental-problem-domains/selection-sort","label":"Selection Sort","docId":"fundamental-problem-domains/selection-sort","unlisted":false},{"type":"link","href":"/concepts/fundamental-problem-domains/quicksort","label":"Quicksort","docId":"fundamental-problem-domains/quicksort","unlisted":false},{"type":"link","href":"/concepts/fundamental-problem-domains/efficient-sorting","label":"Beyond Quadratic Sorting","docId":"fundamental-problem-domains/efficient-sorting","unlisted":false},{"type":"link","href":"/concepts/fundamental-problem-domains/comparing-sorting-algorithms","label":"Comparing Sorting Algorithms","docId":"fundamental-problem-domains/comparing-sorting-algorithms","unlisted":false}],"href":"/concepts/category/2-fundamental-problem-domains"},{"type":"category","label":"3. Algorithm Design Paradigms","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/concepts/algorithm-design-paradigms/brute-force","label":"Brute Force and Exhaustive Search","docId":"algorithm-design-paradigms/brute-force","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/divide-and-conquer","label":"Divide and Conquer","docId":"algorithm-design-paradigms/divide-and-conquer","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/divide-and-conquer-analysis","label":"Analyzing Divide and Conquer","docId":"algorithm-design-paradigms/divide-and-conquer-analysis","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/divide-and-conquer-examples-1","label":"Divide and Conquer: Numbers and Searches","docId":"algorithm-design-paradigms/divide-and-conquer-examples-1","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/divide-and-conquer-examples-2","label":"Divide and Conquer: Classic Problems","docId":"algorithm-design-paradigms/divide-and-conquer-examples-2","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/divide-and-conquer-statistics","label":"Divide and Conquer: Majority, Mode and Median","docId":"algorithm-design-paradigms/divide-and-conquer-statistics","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/greedy-algorithms","label":"Greedy Algorithms","docId":"algorithm-design-paradigms/greedy-algorithms","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/greedy-examples","label":"Greedy Algorithms: Classic Problems","docId":"algorithm-design-paradigms/greedy-examples","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/dynamic-programming","label":"Dynamic Programming","docId":"algorithm-design-paradigms/dynamic-programming","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/dynamic-programming-examples","label":"Dynamic Programming: Classic Problems","docId":"algorithm-design-paradigms/dynamic-programming-examples","unlisted":false}],"href":"/concepts/category/3-algorithm-design-paradigms"},{"type":"category","label":"4. State Space Search and Optimization","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/concepts/state-space-search-and-optimization/backtracking","label":"Backtracking","docId":"state-space-search-and-optimization/backtracking","unlisted":false},{"type":"link","href":"/concepts/state-space-search-and-optimization/backtracking-examples","label":"Backtracking: Classic Problems","docId":"state-space-search-and-optimization/backtracking-examples","unlisted":false},{"type":"link","href":"/concepts/state-space-search-and-optimization/branch-and-bound","label":"Branch and Bound","docId":"state-space-search-and-optimization/branch-and-bound","unlisted":false},{"type":"link","href":"/concepts/state-space-search-and-optimization/branch-and-bound-examples","label":"Branch and Bound: Classic Problems","docId":"state-space-search-and-optimization/branch-and-bound-examples","unlisted":false}],"href":"/concepts/category/4-state-space-search-and-optimization"},{"type":"category","label":"5. Advanced Execution Models","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/concepts/advanced-execution-models/parallel-algorithms","label":"Concurrency and Parallelism","docId":"advanced-execution-models/parallel-algorithms","unlisted":false},{"type":"link","href":"/concepts/advanced-execution-models/fork-join-framework","label":"The Fork/Join Framework","docId":"advanced-execution-models/fork-join-framework","unlisted":false},{"type":"link","href":"/concepts/advanced-execution-models/parallel-performance","label":"Performance of Parallel Algorithms","docId":"advanced-execution-models/parallel-performance","unlisted":false}],"href":"/concepts/category/5-advanced-execution-models"},{"type":"link","href":"/concepts/glossary","label":"Glossary","docId":"glossary","unlisted":false}]},"docs":{"advanced-execution-models/fork-join-framework":{"id":"advanced-execution-models/fork-join-framework","title":"The Fork/Join Framework","description":"Creating and coordinating threads by hand is laborious and error-prone. Since Java 7, the package java.util.concurrent includes the Fork/Join framework, designed precisely to execute divide and conquer algorithms in parallel, using all the available processors automatically. This lesson explains how it works and how to use it, with the examples of the course repository.","sidebar":"tutorialSidebar"},"advanced-execution-models/parallel-algorithms":{"id":"advanced-execution-models/parallel-algorithms","title":"Concurrency and Parallelism","description":"Until now, every algorithm in this course has been sequential: one instruction after another, on a single processor. But the computers we use, from phones to servers, have several processor cores, and a sequential program uses only one of them. Parallel algorithms divide the work so that several cores can do it at the same time.","sidebar":"tutorialSidebar"},"advanced-execution-models/parallel-performance":{"id":"advanced-execution-models/parallel-performance","title":"Performance of Parallel Algorithms","description":"A parallel program is only worth its extra complexity if it is faster. But how much faster can it be? Does doubling the number of cores halve the time? This lesson presents the tools to answer these questions: how the complexity of an algorithm relates to its parallel execution time, how to measure the benefit of parallelism, and Amdahl\'s law, which sets a hard limit on it.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/brute-force":{"id":"algorithm-design-paradigms/brute-force","title":"Brute Force and Exhaustive Search","description":"Brute force is the most direct way to design an algorithm: solve the problem by doing exactly what its statement says, with no attempt to exploit its structure. To find an element, look at every position. To find the best combination, generate every combination and keep the best one. To check whether a text contains a word, try the word at every position of the text.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/divide-and-conquer":{"id":"algorithm-design-paradigms/divide-and-conquer","title":"Divide and Conquer","description":"Divide and conquer is one of the oldest and most powerful strategies for designing algorithms. Instead of attacking a problem as a whole, it breaks it into smaller problems of the same kind, solves them (usually by applying the same strategy again), and combines their solutions. We have already met two examples: binary search, which discards half of the array at each step, and Quicksort, which partitions the array and sorts each part.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/divide-and-conquer-analysis":{"id":"algorithm-design-paradigms/divide-and-conquer-analysis","title":"Analyzing Divide and Conquer","description":"The loops of iterative algorithms can be analyzed by counting iterations, as we did in the first chapter. Recursive algorithms need a different tool: the execution time is expressed in terms of itself applied to smaller sizes, giving a recurrence equation. Fortunately, most divide and conquer algorithms follow one of two very regular patterns, and for both of them the solution is known in general. This lesson presents those two patterns, explains where their formulas come from, and shows how to apply them.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/divide-and-conquer-examples-1":{"id":"algorithm-design-paradigms/divide-and-conquer-examples-1","title":"Divide and Conquer: Numbers and Searches","description":"This lesson applies the paradigm and its analysis to a first set of classic problems: the factorial, sequential and binary search, the Fibonacci numbers and the greatest common divisor. Some of them show the strength of divide and conquer; others, especially Fibonacci, show what happens when it is applied badly. All of them are implemented, with tests, in the course repository.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/divide-and-conquer-examples-2":{"id":"algorithm-design-paradigms/divide-and-conquer-examples-2","title":"Divide and Conquer: Classic Problems","description":"This lesson presents some of the most famous divide and conquer algorithms. Two of them, Mergesort and Quicksort, we already know from the sorting chapter; now we can analyze them with the formulas of this chapter. The others (the Towers of Hanoi, the multiplication of large integers, the tennis tournament and the Tromino puzzle) show how the paradigm solves problems that would be hard to approach in any other way.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/divide-and-conquer-statistics":{"id":"algorithm-design-paradigms/divide-and-conquer-statistics","title":"Divide and Conquer: Majority, Mode and Median","description":"The last group of problems of this chapter comes from statistics this lesson develops the median completely, and leaves the divide and conquer versions of the majority element and the mode as challenges, with hints.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/dynamic-programming":{"id":"algorithm-design-paradigms/dynamic-programming","title":"Dynamic Programming","description":"Divide and conquer breaks a problem into subproblems and combines their solutions. It works beautifully when the subproblems are independent. But we saw in the divide and conquer chapter that the naive recursive Fibonacci solves the same subproblems again and again, and becomes exponential. Dynamic programming keeps the idea of solving a problem through its subproblems, but solves each subproblem only once, storing its solution in a table for later use.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/dynamic-programming-examples":{"id":"algorithm-design-paradigms/dynamic-programming-examples","title":"Dynamic Programming: Classic Problems","description":"This lesson applies the design steps of dynamic programming to several classic problems the change and the cheapest travel on a river. The implementations of the course examples are in the course repository.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/greedy-algorithms":{"id":"algorithm-design-paradigms/greedy-algorithms","title":"Greedy Algorithms","description":"Many problems ask not just for a solution, but for the best one they build the solution step by step and, at each step, they take the choice that looks best right now, without ever reconsidering it.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/greedy-examples":{"id":"algorithm-design-paradigms/greedy-examples","title":"Greedy Algorithms: Classic Problems","description":"This lesson applies the greedy strategy to a series of classic problems. For some of them, a good heuristic gives the optimal solution, and we will see why. For others, it gives only a good solution, and a counterexample shows it. Learning to tell both situations apart is the main goal. The implementations are in the course repository.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/algorithmic-thinking":{"id":"foundations-of-algorithms/algorithmic-thinking","title":"Algorithmic Thinking","description":"In computer science, programming syntax is merely a vehicle for execution. The true engineering core lies in Algorithmics: the systematic study, design and analysis of correct and efficient computational strategies.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/asymptotic-notation":{"id":"foundations-of-algorithms/asymptotic-notation","title":"Asymptotic Notation","description":"In the previous lesson we obtained exact expressions such as $T(n) = 3n + 4$ and saw that the constants depend on arbitrary counting decisions and, in reality, on the machine. What does not depend on them is the rate of growth of the function: how fast $T(n)$ increases when $n$ becomes large.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/case-study-pairwise":{"id":"foundations-of-algorithms/case-study-pairwise","title":"Case Study - Pairwise Product","description":"To truly understand why algorithmics matters, it helps to experience failure first. In this case study we take a deceptively simple problem and solve it again and again. Each version fixes a problem of the previous one, and each fix teaches a different lesson: about the limits of data types, the cost of naive strategies, the impact of data representation, and the danger of \\"optimizations\\" that are not actually correct.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/complexity-analysis":{"id":"foundations-of-algorithms/complexity-analysis","title":"Complexity Analysis","description":"In the previous lesson we saw that measurements depend on the machine, the compiler and the implementation, and that comparing algorithms only by running them has serious limitations. We now develop the alternative: studying the algorithm on paper, by counting how many elementary operations it performs as a function of the size of its input.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/complexity-of-loops":{"id":"foundations-of-algorithms/complexity-of-loops","title":"Complexity of Loops","description":"Most iterative algorithms are, at their core, combinations of loops. Once you can determine quickly and reliably how many times a loop runs, you can analyze almost any iterative program. This lesson collects the most common patterns, explains how to derive each result and points out the traps that appear most often in exams and in real code.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/data-structures":{"id":"foundations-of-algorithms/data-structures","title":"Data Structures","description":"In the previous lessons we saw that the efficiency of a solution depends on the strategy we choose. It also depends, just as much, on how the data is organized in memory. The maximum pairwise product already gave us a hint: the same algorithm used several times more memory with a List than with an int[].","sidebar":"tutorialSidebar"},"foundations-of-algorithms/growth-rates":{"id":"foundations-of-algorithms/growth-rates","title":"Growth Rates and Predictions","description":"Asymptotic notation gives us a precise language. This lesson turns it into practical intuition: what the most common complexity classes mean in real time, how to predict the time an algorithm will need for a larger input, how to estimate the largest input it can handle in a given time, and why no improvement in hardware can change the complexity of an algorithm.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/measuring-efficiency":{"id":"foundations-of-algorithms/measuring-efficiency","title":"Measuring Efficiency","description":"In the case study we compared four strategies for the maximum pairwise product and saw differences ranging from seconds to fractions of a millisecond. But how exactly should we compare algorithms? Is it enough to run them and look at the clock? What should we measure, and how can we trust the numbers?","sidebar":"tutorialSidebar"},"foundations-of-algorithms/searching-case-studies":{"id":"foundations-of-algorithms/searching-case-studies","title":"Searching Case Studies","description":"Searching is one of the most frequent operations in computing: looking up a user in a database, a word in a dictionary, a file in a directory, a value in a cache. In this final lesson of the chapter we apply everything we have learnt to three classic search algorithms. For each one we count instructions exactly, analyze the best, worst and average cases, express the result with asymptotic notation and connect it with real measurements.","sidebar":"tutorialSidebar"},"fundamental-problem-domains/bubble-sort":{"id":"fundamental-problem-domains/bubble-sort","title":"Bubble Sort","description":"Bubble sort is probably the best-known sorting algorithm, and also one of the least efficient. It is worth studying precisely because it is so simple: it lets us practise the exact analysis of comparisons and moves, introduces the important idea of inversions, and shows how small changes (a stop condition, a change of direction) affect the behavior without changing the complexity.","sidebar":"tutorialSidebar"},"fundamental-problem-domains/comparing-sorting-algorithms":{"id":"fundamental-problem-domains/comparing-sorting-algorithms","title":"Comparing Sorting Algorithms","description":"We have studied many sorting algorithms. This lesson brings them together: we compare their behavior with measurements, summarize their properties, give practical guidelines for choosing one, and introduce the sorting of data that does not fit in main memory.","sidebar":"tutorialSidebar"},"fundamental-problem-domains/efficient-sorting":{"id":"fundamental-problem-domains/efficient-sorting","title":"Beyond Quadratic Sorting","description":"Quicksort is not the only way to sort faster than $O(n^2)$. Each of the three basic ideas (exchange, insertion and selection) has an efficient counterpart, and there are also algorithms based on completely different principles. This lesson presents the most important ones, explains the theoretical limit that all comparison-based algorithms share, and shows how some algorithms manage to go below that limit.","sidebar":"tutorialSidebar"},"fundamental-problem-domains/insertion-sort":{"id":"fundamental-problem-domains/insertion-sort","title":"Insertion Sort","description":"Insertion sort is the method most people use, without thinking, to sort a hand of cards it performs fewer comparisons and moves, and it is extremely fast on data that is already almost sorted. For this reason, it is used inside many professional sorting algorithms.","sidebar":"tutorialSidebar"},"fundamental-problem-domains/quicksort":{"id":"fundamental-problem-domains/quicksort","title":"Quicksort","description":"Quicksort, invented by Tony Hoare around 1960, is one of the most important algorithms ever designed. It is the basis of the sorting routines of many programming languages and libraries, and it is usually the fastest general-purpose sorting algorithm in practice. It improves the idea of exchange: instead of exchanging adjacent elements, it exchanges elements that are far apart, removing many inversions at once.","sidebar":"tutorialSidebar"},"fundamental-problem-domains/selection-sort":{"id":"fundamental-problem-domains/selection-sort","title":"Selection Sort","description":"Selection sort follows the most direct strategy imaginable: find the smallest element and put it first; then find the smallest of the rest and put it second; and so on. It is the simple algorithm with the most predictable behavior, the one that performs the fewest exchanges, and, unlike the previous two, it is not stable.","sidebar":"tutorialSidebar"},"fundamental-problem-domains/the-sorting-problem":{"id":"fundamental-problem-domains/the-sorting-problem","title":"The Sorting Problem","description":"Sorting is one of the most frequent operations in any information system, and one of the most thoroughly studied problems in computer science. When there is a certain volume of data, keeping it sorted makes searching (and many other operations) much faster: we saw in the previous chapter that binary search needs about 20 steps to search a million sorted elements, while sequential search may need a million.","sidebar":"tutorialSidebar"},"glossary":{"id":"glossary","title":"Glossary","description":"The main terms of the course, in alphabetical order. Each entry gives a short definition and links to the lesson where the term is explained in detail.","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"Course Overview","description":"These lessons cover the theory of algorithmics you can read them in order as a course, or jump to any topic as a reference.","sidebar":"tutorialSidebar"},"state-space-search-and-optimization/backtracking":{"id":"state-space-search-and-optimization/backtracking","title":"Backtracking","description":"Some problems resist every technique seen so far. There is no greedy criterion that guarantees the optimum, the problem does not split into independent halves, and there is no small table of subproblems to fill. Very often the only way to be sure of the answer is to examine the candidate solutions one by one. Backtracking is the paradigm that organizes that examination so that it is systematic (no candidate is forgotten) and as cheap as possible (whole families of candidates are discarded at once).","sidebar":"tutorialSidebar"},"state-space-search-and-optimization/backtracking-examples":{"id":"state-space-search-and-optimization/backtracking-examples","title":"Backtracking: Classic Problems","description":"This lesson applies the general schemes of backtracking to a series of classic problems. They are ordered from simple to more demanding, and each one illustrates a different aspect of the paradigm:","sidebar":"tutorialSidebar"},"state-space-search-and-optimization/branch-and-bound":{"id":"state-space-search-and-optimization/branch-and-bound","title":"Branch and Bound","description":"Branch and bound (B&B) is the last design technique of the course. Like backtracking, it searches an implicit tree of states: nodes represent states of the problem, edges represent valid changes, and solving the problem means finding a node (or a path) in that tree. The difference is the order in which the tree is explored, and that single change makes it suitable for different problems.","sidebar":"tutorialSidebar"},"state-space-search-and-optimization/branch-and-bound-examples":{"id":"state-space-search-and-optimization/branch-and-bound-examples","title":"Branch and Bound: Classic Problems","description":"This lesson applies the general scheme of branch and bound to several problems. In each one, the work consists of answering the same three questions:","sidebar":"tutorialSidebar"}}}}')}}]);